function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'MapSum' || args[0].length !== 0) return 'Start with MapSum and no arguments.';
  if (operations.length - 1 > 50) return 'At most 50 calls to insert and sum.';
  const word = s => typeof s === 'string' && s.length >= 1 && s.length <= 50 && /^[a-z]+$/.test(s);
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] === 'insert') {
      if (args[i].length !== 2 || !word(args[i][0])) return 'insert needs a key of 1 to 50 lowercase letters and a value.';
      if (!Number.isInteger(args[i][1]) || args[i][1] < 1 || args[i][1] > 1000) return 'val is a whole number from 1 to 1000.';
    } else if (operations[i] === 'sum') {
      if (args[i].length !== 1 || !word(args[i][0])) return 'sum needs a prefix of 1 to 50 lowercase letters.';
    } else return 'Only insert and sum can follow the constructor.';
  }
  return null;
}

