class MapSum {
  constructor() {
    this.root = { children: new Map(), score: 0 };
    this.values = new Map();
  }

  insert(key, val) {
    const delta = val - (this.values.get(key) || 0);
    this.values.set(key, val);
    let node = this.root;
    for (const letter of key) {
      if (!node.children.has(letter)) {
        node.children.set(letter, { children: new Map(), score: 0 });
      }
      node = node.children.get(letter);
      node.score += delta;
    }
  }

  sum(prefix) {
    let node = this.root;
    for (const letter of prefix) {
      node = node.children.get(letter);
      if (node === undefined) {
        return 0;
      }
    }
    return node.score;
  }
}

