class MapSum {
  constructor() {
    this.pairs = {};
  }
  insert(key, val) {
    this.pairs[key] = val;
  }
  sum(prefix) {
    let total = 0;
    for (const key of Object.keys(this.pairs))
      if (key.slice(0, prefix.length) === prefix) total += this.pairs[key];
    return total;
  }
}

