function generate(rand, size) {
  const operations = ['MapSum'];
  const args = [[]];
  const calls = size === 'large' ? 50 : 1 + Math.floor(rand() * 12);
  const letters = size === 'large' ? (rand() < 0.5 ? 'ab' : 'abcdefghijklmnopqrstuvwxyz') : (rand() < 0.7 ? 'ab' : 'abc');
  const maxLen = size === 'large' ? 50 : 4;
  const word = () => {
    const len = 1 + Math.floor(rand() * maxLen);
    let text = '';
    for (let i = 0; i < len; i++) text += letters[Math.floor(rand() * letters.length)];
    return text;
  };
  const keys = [];
  const insertRate = 0.3 + rand() * 0.4;
  for (let i = 0; i < calls; i++) {
    if (rand() < insertRate) {
      const key = keys.length > 0 && rand() < 0.3 ? keys[Math.floor(rand() * keys.length)] : word();
      const val = rand() < 0.1 ? (rand() < 0.5 ? 1 : 1000) : 1 + Math.floor(rand() * 1000);
      keys.push(key);
      operations.push('insert');
      args.push([key, val]);
    } else {
      let prefix;
      if (keys.length > 0 && rand() < 0.7) {
        const key = keys[Math.floor(rand() * keys.length)];
        prefix = key.slice(0, 1 + Math.floor(rand() * key.length));
      } else prefix = word();
      operations.push('sum');
      args.push([prefix]);
    }
  }
  return [operations, args];
}
